Your expense tracker is below. Add each spend with an amount and category, and it shows your total, what is left of your budget, and a split by category. Entries may be lost when you close the chat, so note down your total before you leave.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f6f8;color:#222}
  h1{font-size:20px;margin:0 0 12px}
  .card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select{flex:1;min-width:110px;padding:8px;border:1px solid #ccc;border-radius:8px;font-size:14px}
  button{padding:8px 14px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-size:14px;cursor:pointer}
  button.x{background:#e5e7eb;color:#444;padding:4px 10px}
  .stats{display:flex;gap:8px}
  .stat{flex:1;text-align:center}
  .stat b{display:block;font-size:18px}
  .stat span{font-size:12px;color:#666}
  .bar{height:8px;background:#e5e7eb;border-radius:4px;overflow:hidden;margin:4px 0 10px}
  .bar i{display:block;height:100%;background:#2563eb}
  .over{color:#c0262d}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
  .item small{color:#777;display:block}
  .cat{display:flex;justify-content:space-between;font-size:13px}
  .empty{color:#888;font-size:13px}
</style>
</head>
<body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="stats">
    <div class="stat"><b id="total">₹0</b><span>Spent</span></div>
    <div class="stat"><b id="left">₹0</b><span>Left</span></div>
    <div class="stat"><b id="count">0</b><span>Entries</span></div>
  </div>
  <div class="bar"><i id="used" style="width:0%"></i></div>
</div>

<div class="card">
  <div class="row">
    <input id="name" type="text" placeholder="What for? (e.g. Milk)">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add" type="button">Add</button>
  </div>
</div>

<div class="card">
  <b style="font-size:14px">By category</b>
  <div id="cats" style="margin-top:8px"></div>
</div>

<div class="card">
  <b style="font-size:14px">All entries</b>
  <div id="list"></div>
</div>

<script>
var items=[];
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
function render(){
  var total=0,by={};
  items.forEach(function(e){total+=e.a;by[e.c]=(by[e.c]||0)+e.a;});
  var b=parseFloat(document.getElementById('budget').value)||0;
  document.getElementById('total').textContent=inr(total);
  var left=document.getElementById('left');
  left.textContent=b?inr(b-total):'—';
  left.className=(b&&total>b)?'over':'';
  document.getElementById('count').textContent=items.length;
  document.getElementById('used').style.width=(b?Math.min(100,total/b*100):0)+'%';
  var cats=document.getElementById('cats');cats.innerHTML='';
  var keys=Object.keys(by).sort(function(x,y){return by[y]-by[x];});
  if(!keys.length){cats.innerHTML='<div class="empty">Nothing added yet.</div>';}
  keys.forEach(function(k){
    var d=document.createElement('div');
    d.innerHTML='<div class="cat"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="bar"><i style="width:'+(by[k]/total*100)+'%"></i></div>';
    cats.appendChild(d);
  });
  var list=document.getElementById('list');list.innerHTML='';
  items.slice().reverse().forEach(function(e){
    var d=document.createElement('div');d.className='item';
    var l=document.createElement('div');
    var s=document.createElement('span');s.textContent=e.n;
    var sm=document.createElement('small');sm.textContent=e.c;
    l.appendChild(s);l.appendChild(sm);
    var r=document.createElement('div');
    r.appendChild(document.createTextNode(inr(e.a)+' '));
    var x=document.createElement('button');x.type='button';x.className='x';x.textContent='✕';
    x.onclick=function(){items=items.filter(function(i){return i.id!==e.id;});render();};
    r.appendChild(x);
    d.appendChild(l);d.appendChild(r);list.appendChild(d);
  });
}
document.getElementById('add').onclick=function(){
  var n=document.getElementById('name').value.trim();
  var a=parseFloat(document.getElementById('amt').value);
  if(!n||!(a>0))return;
  items.push({id:Date.now()+Math.random(),n:n,a:a,c:document.getElementById('cat').value});
  document.getElementById('name').value='';
  document.getElementById('amt').value='';
  render();
};
document.getElementById('budget').oninput=render;
render();
</script>
</body>
</html>
```

Here's your water tracker for Sat 24 Oct. Tap a glass to fill it, and the ring shows how close you are to 8.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:20px;text-align:center;background:#f3f8fc;color:#123}
h1{font-size:20px;margin:0 0 4px}
#day{color:#567;font-size:13px;margin-bottom:16px}
#ring{width:140px;height:140px;border-radius:50%;margin:0 auto 12px;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:600}
#msg{min-height:20px;margin-bottom:14px;font-size:14px}
#glasses{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;max-width:340px;margin:0 auto 16px}
.g{width:60px;height:70px;border:2px solid #3a8fd6;border-radius:6px 6px 14px 14px;background:#fff;font-size:26px;cursor:pointer}
.g.on{background:#8cc8f5}
.row button{padding:8px 16px;margin:0 4px;border:0;border-radius:8px;background:#3a8fd6;color:#fff;font-size:14px;cursor:pointer}
.row button.alt{background:#8a99a8}
</style></head><body>
<h1>Water today</h1>
<div id="day">Sat 24 Oct</div>
<div id="ring"><span id="count">0 / 8</span></div>
<div id="msg"></div>
<div id="glasses"></div>
<div class="row">
<button type="button" id="minus" class="alt">− Remove one</button>
<button type="button" id="plus">+ Add a glass</button>
<button type="button" id="reset" class="alt">Reset</button>
</div>
<script>
var GOAL=8,KEY="water-2026-10-24",n=0;
try{n=parseInt(localStorage.getItem(KEY))||0}catch(e){}
var box=document.getElementById("glasses");
for(var i=0;i<GOAL;i++){(function(i){
var b=document.createElement("button");b.type="button";b.className="g";b.textContent="💧";
b.onclick=function(){n=(n===i+1)?i:i+1;draw()};box.appendChild(b)})(i)}
function draw(){
n=Math.max(0,Math.min(GOAL+4,n));
var p=Math.min(n/GOAL,1)*360;
document.getElementById("ring").style.background="conic-gradient(#3a8fd6 "+p+"deg,#dbe6ef 0deg)";
document.getElementById("count").textContent=n+" / "+GOAL;
document.getElementById("count").style.cssText="background:#f3f8fc;border-radius:50%;width:104px;height:104px;display:flex;align-items:center;justify-content:center";
var g=box.children;for(var i=0;i<g.length;i++)g[i].className="g"+(i<n?" on":"");
document.getElementById("msg").textContent=n>=GOAL?"Goal reached. Well done!":(GOAL-n)+" more to go";
try{localStorage.setItem(KEY,n)}catch(e){}
}
document.getElementById("plus").onclick=function(){n++;draw()};
document.getElementById("minus").onclick=function(){n--;draw()};
document.getElementById("reset").onclick=function(){n=0;draw()};
draw();
</script></body></html>
```
